const newFrame=():FloorFrame=>({x:0,y:0,width:24,height:80,rotation:0});
function sceneFromURL():Scene|null{const q=new URL(location.href).searchParams;if(q.has("craftNew"))return {craftId:q.get("craftNew")!,surface:"exterior",creation:"craft"};if(!q.has("craft"))return null;return {craftId:q.get("craft")!,surface:q.get("craftDeckNew")??q.get("craftDeck")??"exterior",creation:q.has("craftDeckNew")?"deck":false,route:q.get("craftRoute")??undefined};}
function changeURL(scene:Scene|null){const u=new URL(location.href),parentDeck=u.searchParams.has("atlasYear")?u.searchParams.get("craftDeck"):null;for(const key of ["craft","craftNew","craftDeck","craftDeckNew","craftLibrary","craftArrival","craftRoute"])u.searchParams.delete(key);if(!scene)u.searchParams.set("craftLibrary","1");else if(scene.creation==="craft")u.searchParams.set("craftNew",scene.craftId);else{u.searchParams.set("craft",scene.craftId);if(scene.creation==="deck"){u.searchParams.set("craftDeckNew",scene.surface);if(parentDeck)u.searchParams.set("craftDeck",parentDeck);}else if(scene.surface!=="exterior")u.searchParams.set("craftDeck",scene.surface);}if(scene?.arrival)u.searchParams.set("craftArrival",JSON.stringify(scene.arrival));if(scene?.route)u.searchParams.set("craftRoute",scene.route);replaceNativeAtlasUrl(u.pathname+u.search);}
